atus<select name="status"><option <?=$customer['status']==='Active'?'selected':''?>>Active</option><option <?=$customer['status']==='Inactive'?'selected':''?>>Inactive</option></select></label></div><div class="actions"><a class="btn light" href="index.php">Back</a><button class="btn primary">Update Customer</button></div></form></div></main><?php require_once __DIR__.'/../../includes/footer.php';